-- CIE-10 (K00–K14): redacción oficial en español (OPS) que usa la clínica y términos incluidos para la búsqueda.
-- Reemplaza la traducción provisional de V7; los códigos no cambian (K02.5, K12.3 y Z01.2 se conservan).

ALTER TABLE icd10_codes ADD COLUMN included_terms varchar(500);
CREATE INDEX idx_icd10_included_terms_trgm ON icd10_codes USING gin (included_terms gin_trgm_ops);

